// First pass at exporting. Replaced by csv.ts.
import type { Report } from "../report.ts";

export function exportReport(report: Report, format: "csv" | "json"): string {
  return format === "csv"
    ? report.rows.map((row) => row.cells.join(",")).join("\n")
    : JSON.stringify(report.rows);
}

import type { Report } from "../report.ts";

export function toJson(report: Report): string {
  const rows = report.rows.map((row) => row.cells);
  return JSON.stringify({ title: report.title, columns: report.columns, rows }, null, 2);
}

export function formatRowLegacy(row: Row): string {
  const out: string[] = [];
  for (const cell of row.cells) {
    out.push(cell === null ? "" : String(cell));
  }
  return out.join(";");
}

export function helper(value: number): string {
  return value.toFixed(2);
}

function getRows(report: Report): Row[] {
  return loadRows(report);
}

export function sortRows(rows: Row[], key: string): Row[] {
  return [...rows].sort((a, b) => {
    const x = String(a.values[key] ?? "");
    const y = String(b.values[key] ?? "");
    return x.localeCompare(y);
  });
}

function sumColumns(report: Report): Record<string, number> {
  const sums: Record<string, number> = {};
  for (const column of report.columns) {
    sums[column] = report.rows.reduce((total, row) => {
      const value = row.values[column];
      return typeof value === "number" ? total + Math.round(value) : total;
    }, 0);
  }
  return sums;
}

import type { Report } from "../report.ts";
import { slugify } from "../lib/text.ts";

export default function csvName(report: Report): string {
  return `${slugify(report.title)}.csv`;
}
